import{_ as t,a as o}from"./chunks/e1b3924c2f88d6dab899.CzDXrQRY.js";import{_ as i,o as n,c as a,a5 as s}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"The Best Online Business Model To Make $1 Million In 2023","description":"","frontmatter":{"title":"The Best Online Business Model To Make $1 Million In 2023","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/the-best-online-business-model-to-make-1-million-in-2023.md","filePath":"en/letters/the-best-online-business-model-to-make-1-million-in-2023.md"}'),r={name:"en/letters/the-best-online-business-model-to-make-1-million-in-2023.md"};function l(h,e,p,u,c,d){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="the-best-online-business-model-to-make-1-million-in-2023" tabindex="-1">The Best Online Business Model To Make $1 Million In 2023 <a class="header-anchor" href="#the-best-online-business-model-to-make-1-million-in-2023" aria-label="Permalink to &quot;The Best Online Business Model To Make $1 Million In 2023&quot;">​</a></h1><p>Dan Koe · 2023-03-10 · <a href="https://thedankoe.com/letters/the-best-online-business-model-to-make-1-million-in-2023/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/the-best-online-business-model-to-make-1-million-in-2023">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/ueeIJcjWZh8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>This is quite possibly the most popular topic in the self-improvement space.</p><p>These types of posts always do well:</p><ul><li>The best side hustles to start in 2023</li><li>The best online business model in 2023</li><li>How to get RICH and stop being so POOR in 2023!!!! (please CLICK now or you will have 10 YEARS of BAD luck!)</li></ul><p>I’m tired of the last example too.</p><p>All of these videos, posts, and articles lack one crucial aspect:</p><p><em>A big picture overview of online business.</em></p><p>They focus on the technical skills, models, and outreach strategies to make money as fast as possible.</p><p>As always, there’s nothing wrong with this.</p><p>I’m just here to paint new perspectives and open your mind.</p><p>The problem is that <em>everyone</em> wants quick results.</p><p><em>Everyone</em>.</p><p>I did (and still do) too.</p><p>I’m here to tell you that it may not work, and even if it does, it won’t be around in the next 3 months because you’re fighting other bottom feeders that lack purpose behind their work.</p><p>Because they are in a state of survival that doesn’t allow them to even consider <a href="https://thedankoe.com/the-rise-of-the-value-creator-a-new-career-path/" target="_blank" rel="noreferrer">their <em>life’s work.</em></a></p><p>Similar to the short-form content and ghostwriting rat race going on right now.</p><p>I get 100s of DMs and emails from people pitching the same Walmart quality reels captions (all you gotta do is learn an actual software – not CapCut – and stop trying to take shortcuts bros).</p><p>People don’t care to get good, they care to get money.</p><p>That’s a brutal mistake.</p><p>I went through the same phase as everyone else though.</p><p>Most people do.</p><p>So treat this as a seed of awareness on your business journey.</p><p>If you are chasing the quick bucks with the latest strategies, you have about 3-6 months left before you need to pivot, give up, or prioritize becoming the best.</p><h2 id="what-is-the-best-business-model" tabindex="-1">What Is The Best Business Model? <a class="header-anchor" href="#what-is-the-best-business-model" aria-label="Permalink to &quot;What Is The Best Business Model?&quot;">​</a></h2><p>The best business model is an actual business model.</p><p>Not a side hustle.</p><p>Not free online surveys.</p><p>Not investing your weekly allowance into crypto.</p><p>A business has to generate revenue. You need cash flow.</p><p>A business has the ability to scale, pivot, and position itself in the market regardless of algorithm changes and trends.</p><p>Half of the short-form content people will be out of a job because they don’t understand marketing (I’m not talking about a surface-level knowledge here, I’m talking about deep experience).</p><p><strong>Money Is The Lifeblood Of Society</strong></p><p>Like how your hand will die if blood stops flowing, so will your business, and therefore your sense of purpose.</p><p>Purpose is something greater than you.</p><p>If you aren’t making money, it means you aren’t contributing to society with the value you have to offer.</p><p>Business is how you make money, therefore it is how you contribute to society, therefore it is a valid purpose in your life.</p><p>Business is a vessel for your value and nothing more.</p><p>Online surveys, prescriptive business models (like short-form content agencies), and most jobs are soulless.</p><p><strong>A Business Has An Offer &amp; Traffic Source</strong></p><p>This is a universal principle beyond business.</p><p>Offer = value</p><p>Traffic = people</p><p>You need to place a valuable product or service in front of a group of people that want to buy.</p><p>Like putting a hot dog stand outside of a music festival with a bunch of drunk people walking by.</p><p>Or, in dating, putting yourself in an environment where your ideal partner is so you actually have a chance of landing a date.</p><p>If you have an offer, but no traffic, why are you complaining about not getting any sales (or dates)?</p><p><strong>The Dynamic Traffic Source</strong></p><p>I’m not a fan of putting yourself in a box, and I’m bullish on the <a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">creator economy as a way of life</a>.</p><p>It is the <em>new economy</em> regardless of if you care to start a business or become a creator.</p><p>Therefore, a personal brand is the closest thing to a “one size fits all” traffic source.</p><p>A personal brand is how <a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">you become the niche</a> and eradicate competition.</p><p>With a personal brand:</p><ul><li>You don’t have to rely on ads</li><li>You can talk about whatever you want (<a href="https://thedankoe.com/dont-get-replaced-by-ai-how-to-write-authentic-content/" target="_blank" rel="noreferrer">if you sprinkle in content related to your offer</a>)</li><li>You don’t have to rely on cold outreach (for long)</li><li>You build an audience so you can do whatever you want</li><li>Your business doesn’t die when you stop doing the manual work</li><li>You aren’t cornered into a specific niche, like how Zuby not only talks about politics, but makes music and sells fitness programs (most people just can’t get out of the scarcity mindset of needing to land clients, so their content feels limited and boring).</li></ul><p>And, you get to meet like-minded people, travel the world, and actually enjoy your work.</p><p>I just got back from a trip to see Joey Justice and Justin Scott. You won’t find the conversations we had in your everyday life.</p><p><img src="'+t+'" alt=""></p><p>I don’t care to convince you on this, because you will come to this conclusion eventually.</p><p><strong>The lesson:</strong></p><p>A personal brand should be considered your foundational traffic source for your offers.</p><p>Paid ads increase in authority when people know your name.</p><p>Cold outreach to your audience makes them open to talking to you (they actually respond).</p><p>You can pivot whenever you’d like if you understand that content is about value, not writing about specific topics.</p><p>In other words, you write content based on ideas, not topics, and articulate those ideas from the lens of a relevant goal or problem. Topics help with idea generation.</p><p>Nobody cares about the topic, they care about how anything and everything will benefit their life.</p><h2 id="the-experience-model" tabindex="-1">The Experience Model <a class="header-anchor" href="#the-experience-model" aria-label="Permalink to &quot;The Experience Model&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>I’ve talked about personal brand strategies many times in the past, so I’ll leave it at that.</p><p>Instead, I want to focus more on offer creation.</p><p>Most people think they need:</p><ul><li>The perfect customer avatar</li><li>The perfect system, curriculum, or coaching structure</li><li>A fancy physical product with perfected supply chain management</li><li>Prior results (when you need to actually work with someone to get results)</li></ul><p>In reality, <em>you need to <strong>know</strong> more than someone who is one step behind you.</em></p><p>See: the terms “age of information” and “attention economy”. Knowledge is king.</p><p>Everything in this world goes through developmental stages.</p><p>It doesn’t matter if it’s the globe and its seasons, progress in society, or you reaching a new level in life.</p><p>Business is no different, and if you haven’t started, you aren’t going to hit level 10 in 2 weeks making $1 million a year.</p><p>This is common sense but most people set that expectation thanks to human nature, social media headlines, and the collective quick-fix mindset.</p><p>We have to start small.</p><h3 id="the-minimum-viable-offer" tabindex="-1">The Minimum Viable Offer <a class="header-anchor" href="#the-minimum-viable-offer" aria-label="Permalink to &quot;The Minimum Viable Offer&quot;">​</a></h3><p>I’ve talked about this briefly before in <a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">The One Person Business Model letter</a>, but I want to give you the dirty deets.</p><p>A minimum viable offer revolves around a <em><strong>single</strong></em> skill or interest.</p><p>Charging big bucks takes time, experience, and multidisciplinary skill acquisition while building in the real world (not reading about working with them).</p><p>With your single skill or interest, you immediately turn it into a relevant freelance, coaching, consulting, or tutoring offer.</p><p>When I say “skill,” I mean anything like:</p><ul><li>Email marketing</li><li>Web design</li><li>Copywriting</li><li>Facebook ads</li><li>Brand design</li><li>Anything else from the <a href="https://thedankoe.com/the-1-million-dollar-skill-stack-learn-in-this-order/" target="_blank" rel="noreferrer">$1 Million Dollar Skill Stack</a></li></ul><p>By “interest” I mean anything like:</p><ul><li>Health and fitness</li><li>Performance and productivity</li><li>Personal development and spirituality</li><li>Relationships or dating</li></ul><p>Those are skills, yes, but I want to make the distinction here to help frame what we are talking about.</p><p><strong>Packaging Up Your Offer Fast</strong></p><p>With a skill, it should be fairly obvious.</p><p>You would either sell website design, landing page design, email marketing, sales page copywriting, or a brand design service like a profile banner, profile picture, and ebook cover design.</p><p>In essence, you can take a beginner level course, watch some YouTube videos, and start selling (remember that you aren’t trying to charge insane amounts here… <em>you have to develop your offer, and you can’t develop what doesn’t exist</em>).</p><p>Anyone can pick up one of these skills fast and start landing clients from your personal brand.</p><p>I’ve written plenty of letters on this in the past, but there are 10+ courses and 180+ strategies in <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Modern Mastery</a> to help you do this. Or the <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> masterclass to productize yourself with my personal systems.</p><p><strong>For Coaching, Consulting, Or Tutoring Offers</strong></p><p>First, understand this universal principle:</p><ul><li>Goal (where your customer wants to be)</li><li>Path (your unique way of getting them there)</li><li>Problem (what they are struggling with now)</li></ul><p>In a nutshell, that’s all that marketing is.</p><p>You are selling a <em>transformation</em> that either you have achieved yourself, you have helped others achieve, or you want to start helping others achieve.</p><p><strong>Remember</strong>: <em>freelancers gain experience by working with clients first. Most of them don’t have a business to do it themselves first. They just learn the skill and start selling it to their ideal customer. You don’t have to have prior results to get started… because you get results by helping yourself <strong>or</strong> helping others.</em></p><p>Coaching and consulting offers are fairly obvious, you help them with an interest like fitness, productivity, or something else in their life.</p><p>For a tutoring offer, you will be <em><strong>teaching</strong></em> them the skill instead of doing it for them. Think of it like you are walking them through a course one-on-one.</p><ul><li>Teaching them how to write an email newsletter</li><li>Teaching them how to edit YouTube videos</li><li>Teaching them how to write social media content</li><li>Teaching them web or graphic design</li></ul><p>This is an alternate option to freelancing. You teach them instead of doing it for them.</p><p>This works incredible for targeting beginners. More people should create a tutoring offer (if you are beginner or intermediate, I would do a tutoring offer and skip the pain that comes with freelancing… it also helps you write about anything you want to beginners in your content).</p><p>And the results you get transfer over into a digital product / course much easier.</p><p>The reason you are doing this, instead of a course, as a beginner is because:</p><ul><li>You can charge more (and increase prices to $2,500+ after a few clients)</li><li>You don’t have an audience (traffic) to bring in consistent course sales</li><li>You don’t know what gets results yet (even if you think you do, you don’t), that’s why you work 1-1 and refine along the way</li><li>You can use direct outreach methods or <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">different strategies</a> to acquire clients</li></ul><p>In short, it’s “easier” to make a $1000 sale instead of ten $100 sales.</p><p>You start to realize that you are in full control of your income.</p><p>That’s liberating.</p><p>Coaching, consulting, or tutoring offers consist of a few things:</p><p><strong>1) A structure for what you are going to teach or help them with.</strong></p><p>Think of where they are now (point A) and what you help them achieve (point B).</p><p>Now, create a soft outline of the necessary things they need to learn and do.</p><p>This does not have to turn into a curriculum, because you will be walking them through everything on a call.</p><p>Most coaches, consultants, etc are selling programs that are direct teachings from their courses or book.</p><p>Yes, the exact same thing, because that’s their method for getting results. The difference is 1-1 help and accountability.</p><p><strong>If you want to structure your teachings well:</strong></p><ul><li>Define what point A is (where they are now and the problem they are experiencing)</li><li>Befine what point B is (the desirable point in life that you can help them reach)</li><li>The path to get there – outline chapters of a book or modules in a course – you can use others’ books or courses for inspiration to make sure you aren’t missing anything.</li><li>Fill this in as you see fit. You can incorporate multiple interests if you’d like… you don’t have to limit it to one specific interest and be the same as everyone else. Think of how a book synthesizes multiple teachings to get to one outcome.</li></ul><p><strong>2) Weekly calls to answer questions and teach them what they need to know.</strong></p><p>I recommend selling a pack of 4 calls. One every week.</p><p>You will be teaching them exactly what they need to know and answer any questions they have.</p><p>Start with 4 calls, because that allows you to charge more at the start.</p><p>And, you probably won’t be able to get them to their desired end result (point B) in one call.</p><p>4 calls allows you to create a more enticing offer than just “I’ll get on a consultation call with you to help you with whatever you are struggling with.”</p><p>You are marketing a transformation.</p><p><strong>3) Weekly Action Items &amp; Text Access</strong></p><p>After every call, you should tell them exactly what they should do.</p><p>You can create worksheets, tasks, or projects for them to complete.</p><p>If you are selling health coaching, have them track their food and weigh themselves each morning.</p><p>If you are selling design tutoring, have them create a first iteration of a social media design.</p><p>You should have a way of communicating with them outside of calls, like on Telegram, Whatsapp, or just texting on your phone.</p><p><strong>Charge $500-$1000 At The Start</strong></p><p>For a single-skill freelance service OR pack of 4 calls (coaching, consulting, or tutoring) you will start at $500, increase to $1000 after the first few clients, and continue improving your offer from there as you go through this course.</p><p>Even better, I would recommend helping people for free.</p><p>If you are a creator and are <a href="https://thedankoe.com/how-to-network-with-millionaires-and-build-a-name-for-yourself/" target="_blank" rel="noreferrer">networking with other creators</a>, offer them a few calls for free.</p><p>As you both grow, their testimonial will increase in value.</p><p>A testimonial from me at 500 followers is worth tens of thousands of dollars when I have 1 million followers. People will buy the product just because they see my name associated with it.</p><p><em>Testimonials from creators are appreciating assets.</em></p><p>Don’t only try to land big fish because you are desperate for money.</p><p>Slow and steady.</p><p><strong>You Can Either Scale Your Client Business Or Productize</strong></p><p>As you are growing your brand, getting client results, and refining your offer through skill acquisition (never stop learning)… you have 2 options.</p><ol><li>Create a more compelling offer and increase your prices.</li><li>Turn your curriculum into a cohort-based course and use your audience to fuel it (only works for coaching, consulting, or tutoring)</li></ol><p>I, of course, recommend the second option.</p><p>It gives you more free time, less stress, and more leverage.</p><p>Leverage leverage leverage.</p><p>The main downside is that you will need to be consistently growing your audience to fuel the cohort. That is difficult, but oh so worth it instead of getting trapped in a feast or famine freelance cycle.</p><p>Then, once your cohort gets results and testimonials, you can productize further into a self-paced course.</p><p>Now, you don’t have to do any work, and can spend your free time building higher ROI projects.</p><p>As we discussed in the last letter, you desaturate the market beneath you.</p><p>The creator economy cannot get saturated.</p><p><strong>Scale To One Million</strong></p><p>$1 million becomes inevitable if:</p><ul><li>You don’t stagnate with one underpaying offer</li><li>You continue growing your following (yes, this is possible, don’t stagnate and blame the algorithm for your lack of knowledge of social media)</li><li>You evolve, your offers evolve, and you increase your income while decreasing the time you spend on work</li></ul><p>The route I took to do this was with a personal brand, digital products, and endless iteration.</p><p>It took me 3 years (with a bit of prior experience).</p><p>Hopefully, my content can help you get there faster.</p><p>– Dan</p>',161)])])}const y=i(r,[["render",l]]);export{g as __pageData,y as default};
